// ─────────────────────────────────────────────────────────────────────────────
// PUT /api/payment-receipts/:id/bounce  — Cheque Bounce (NO TRANSACTIONS)
// ─────────────────────────────────────────────────────────────────────────────
const bouncePayment = async (req, res) => {
  try {
    const { bounce_reason } = req.body;
    if (!bounce_reason?.trim()) {
      return err(res, 'bounce_reason is required', 400);
    }

    // Find the payment receipt
    const receipt = await PaymentReceipt.findById(req.params.id);
    if (!receipt) return err(res, 'Payment receipt not found', 404);
    
    // Validate receipt status
    if (receipt.status !== 'Active') {
      return err(res, `Cannot bounce a receipt in status: ${receipt.status}`, 400);
    }
    
    // Check if payment mode is Cheque or DD
    if (receipt.payment_mode !== 'Cheque' && receipt.payment_mode !== 'DD') {
      return err(res, `Bounce is only applicable for Cheque or DD payments. Mode: ${receipt.payment_mode}`, 400);
    }

    // Reverse allocations from invoices
    for (const alloc of receipt.allocations) {
      try {
        const inv = await SalesInvoice.findById(alloc.invoice_id);
        if (!inv) continue;
        
        // Remove the payment allocation from invoice
        inv.payment_allocations = inv.payment_allocations.filter(
          pa => String(pa.payment_receipt_id) !== String(receipt._id)
        );
        await inv.save();
      } catch (invErr) {
        console.error(`[bouncePayment] Error reversing allocation:`, invErr.message);
      }
    }

    // Create GL reversal entry
    try {
      const reversalLines = [
        { 
          account_code: '1010', 
          account_name: 'Bank Account', 
          debit: 0, 
          credit: receipt.net_received, 
          narration: `Cheque bounce reversal — ${receipt.receipt_no}` 
        },
        { 
          account_code: '1100', 
          account_name: 'Trade Receivables', 
          debit: receipt.total_amount, 
          credit: 0, 
          narration: `Bounce reversal — ${receipt.receipt_no}` 
        },
      ];
      
      if (receipt.tds_amount > 0) {
        reversalLines.push({ 
          account_code: '1150', 
          account_name: 'TDS Receivable', 
          debit: 0, 
          credit: receipt.tds_amount, 
          narration: `TDS reversal — ${receipt.receipt_no}` 
        });
      }

      const reversalEntry = await postGLEntry({
        entry_type: 'Cheque Bounce Reversal',
        reference_doc_type: 'PaymentReceipt',
        reference_doc_id: receipt._id,
        reference_doc_no: receipt.receipt_no,
        lines: reversalLines,
        narration: `Cheque bounce: ${receipt.receipt_no} — ${bounce_reason.trim()}`,
        created_by: req.user._id,
        entry_date: new Date(),
      });

      // Update receipt with bounce information
      receipt.status = 'Bounced';
      receipt.bounced_at = new Date();
      receipt.bounce_reason = bounce_reason.trim();
      receipt.reversal_gl_entry_ids = [reversalEntry._id];
      receipt.updated_by = req.user._id;
      await receipt.save();
      
      const result = {
        receipt_no: receipt.receipt_no,
        status: 'Bounced',
        allocations_reversed: receipt.allocations.length,
        reversal_entry_no: reversalEntry.entry_no,
      };
      
      return ok(res, { message: 'Cheque bounced — all allocations reversed', data: result });
      
    } catch (glError) {
      console.error('[bouncePayment] GL reversal failed:', glError);
      // Still update receipt status even if GL fails
      receipt.status = 'Bounced';
      receipt.bounced_at = new Date();
      receipt.bounce_reason = bounce_reason.trim();
      receipt.updated_by = req.user._id;
      await receipt.save();
      
      return ok(res, { 
        message: 'Cheque bounced (GL reversal failed, please check accounting)', 
        data: {
          receipt_no: receipt.receipt_no,
          status: 'Bounced',
          allocations_reversed: receipt.allocations.length,
          gl_error: glError.message
        }
      });
    }
    
  } catch (e) {
    console.error('[bouncePayment] Error:', e);
    return err(res, e.message, e.message.includes('not found') ? 404 : 400);
  }
};

