// ─────────────────────────────────────────────────────────────────────────────
// POST /api/customer-advances  — Create Customer Advance
// ─────────────────────────────────────────────────────────────────────────────
const createCustomerAdvance = async (req, res) => {
  try {
    const body = req.body;
    if (!body.customer_id)  return err(res, 'customer_id is required', 400);
    if (!body.total_amount || Number(body.total_amount) <= 0) return err(res, 'total_amount must be > 0', 400);
    if (!body.payment_mode) return err(res, 'payment_mode is required', 400);

    const customer = await Customer.findById(body.customer_id);
    if (!customer) return err(res, 'Customer not found', 404);

    const advance = await CustomerAdvance.create({
      customer_id:    customer._id,
      customer_name:  customer.customer_name,
      advance_date:   body.advance_date ? new Date(body.advance_date) : new Date(),
      payment_mode:   body.payment_mode,
      total_amount:   Number(body.total_amount),
      instrument_no:  body.instrument_no || '',
      instrument_date:body.instrument_date ? new Date(body.instrument_date) : null,
      bank_name:      body.bank_name || '',
      remarks:        body.remarks || '',
      created_by:     req.user._id,
    });

   // Post GL Entry — don't fail advance creation if GL posting fails
    try {
      const glEntry = await postGLEntry({
        journal_date:         advance.advance_date,
        entry_type:           'Advance Receipt',
        reference_doc_type:   'CustomerAdvance',
        reference_doc_id:     advance._id,
        reference_doc_number: advance.advance_no,
        entries: [
          {
            account_code: '1010',
            account_name: 'Bank Account',
            account_type: 'Asset',
            debit:        advance.total_amount,
            credit:       0,
            description:  `Advance from ${customer.customer_name}`,
          },
          {
            account_code: '2300',
            account_name: 'Customer Advance Liability',
            account_type: 'Liability',
            debit:        0,
            credit:       advance.total_amount,
            description:  `Advance — ${advance.advance_no}`,
          },
        ],
        narration:  `Customer advance from ${customer.customer_name}`,
        created_by: req.user._id,
      });

      await CustomerAdvance.updateOne(
        { _id: advance._id },
        { $set: { gl_posted: true, gl_entry_ids: [glEntry._id] } }
      );
    } catch (glError) {
      console.error('[createCustomerAdvance] GL posting failed:', glError);
      // advance record still stands — gl_posted stays false, can be re-posted later
    }

    const result = await CustomerAdvance.findById(advance._id).lean();
    return ok(res, { message: 'Customer advance recorded', data: result }, 201);
  } catch (e) {
    console.error('[createCustomerAdvance] Error:', e);
    return err(res, e.message);
  }
};

