// PUT /api/invoices/:id/apply-advance  — Apply advance to invoice (NO TRANSACTIONS)
const applyAdvanceToInvoice = async (req, res) => {
  try {
    const { advance_id, amount } = req.body;
    if (!advance_id) throw new Error('advance_id is required');
    if (!amount || Number(amount) <= 0) throw new Error('amount must be > 0');

    // Get invoice and advance
    const invoice = await SalesInvoice.findById(req.params.id);
    const advance = await CustomerAdvance.findById(advance_id);

    if (!invoice) return err(res, 'Invoice not found', 404);
    if (!advance) return err(res, 'Customer advance not found', 404);
    
    if (String(invoice.customer_id) !== String(advance.customer_id)) {
      return err(res, 'Advance does not belong to the same customer as this invoice', 400);
    }

    const applyAmt = Math.min(Number(amount), advance.balance, invoice.balance_due);
    if (applyAmt <= 0) {
      return err(res, 'No applicable amount to adjust. Check advance balance and invoice balance.', 400);
    }

    // Update invoice
    invoice.payment_allocations.push({
      payment_receipt_id: advance._id,
      receipt_no: advance.advance_no,
      allocated_amount: +applyAmt.toFixed(2),
      allocated_on: new Date(),
    });
    await invoice.save();

    // Update advance
    advance.adjustments.push({
      invoice_id: invoice._id,
      invoice_no: invoice.invoice_no,
      adjusted_amount: +applyAmt.toFixed(2),
      adjusted_on: new Date(),
      adjusted_by: req.user._id,
    });
    await advance.save();

    const result = {
      invoice_no: invoice.invoice_no,
      advance_no: advance.advance_no,
      applied_amount: +applyAmt.toFixed(2),
      invoice_balance_due: invoice.balance_due,
      advance_balance: advance.balance,
    };

    return ok(res, { message: 'Advance applied to invoice', data: result });
  } catch (e) {
    console.error('[applyAdvanceToInvoice] Error:', e);
    return err(res, e.message, 400);
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/tds-reconciliation/:customer_id/:year
// ─────────────────────────────────────────────────────────────────────────────
const getTdsReconciliation = async (req, res) => {
  try {
    const { customer_id, year } = req.params;
    if (!mongoose.Types.ObjectId.isValid(customer_id)) return err(res, 'Invalid customer_id', 400);
    const y = parseInt(year);
    if (!y || y < 2000 || y > 2099) return err(res, 'Invalid year', 400);

    const receipts = await PaymentReceipt.find({
      customer_id,
      tds_applicable: true,
      tds_amount:     { $gt: 0 },
      status:         'Active',
      receipt_date: {
        $gte: new Date(`${y}-04-01`),
        $lte: new Date(`${y + 1}-03-31`),
      },
    }).lean();

    const totalTds = receipts.reduce((s, r) => s + r.tds_amount, 0);
    const bySection = {};
    receipts.forEach(r => {
      const sec = r.tds_section || 'Unknown';
      if (!bySection[sec]) bySection[sec] = { section: sec, receipts: 0, total_tds: 0 };
      bySection[sec].receipts++;
      bySection[sec].total_tds += r.tds_amount;
    });

    return ok(res, {
      data: {
        customer_id,
        financial_year: `${y}-${String(y + 1).slice(2)}`,
        total_receipts: receipts.length,
        total_tds:      +totalTds.toFixed(2),
        by_section:     Object.values(bySection).map(s => ({ ...s, total_tds: +s.total_tds.toFixed(2) })),
        receipts,
      },
    });
  } catch (e) {
    return err(res, e.message);
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// HELPER — Auto-close Sales Orders after payment
// ─────────────────────────────────────────────────────────────────────────────
async function autoCloseSalesOrders(invoices, session) {
  const soIds = [...new Set(invoices.map(i => String(i.so_id)).filter(Boolean))];
  for (const soId of soIds) {
    try {
      const so = await SalesOrder.findById(soId).session(session);
      if (!so || ['Closed', 'Cancelled'].includes(so.status)) continue;

      const activeLines = so.items.filter(i => !i.is_cancelled);
      const allDelivered = activeLines.every(i => i.item_status === 'Delivered');
      if (!allDelivered) continue;

      const soInvoices = await SalesInvoice.find({
        so_id:     so._id,
        is_active: true,
        status:    { $nin: ['Cancelled'] },
      }).session(session);
      if (soInvoices.length === 0) continue;
      const allPaid = soInvoices.every(inv => inv.payment_status === 'Fully Paid');
      if (!allPaid) continue;

      so.status = 'Closed';
      so.closed_at = new Date();
      so.audit_log = so.audit_log || [];
      so.audit_log.push({
        changed_by: new mongoose.Types.ObjectId(),
        action:     'status_change',
        old_value:  so.status,
        new_value:  'Closed',
        notes:      'Auto-closed: all items delivered and all invoices fully paid',
      });
      await so.save({ session });
      console.log(`[autoCloseSO] SO ${so.so_number} auto-closed`);
    } catch (soErr) {
      console.error(`[autoCloseSO] Error for SO ${soId}:`, soErr.message);
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// ██  BE-014  POST /api/credit-notes  — Create Credit Note
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// ██  BE-014  POST /api/credit-notes  — Create Credit Note (NO TRANSACTIONS)
// ─────────────────────────────────────────────────────────────────────────────
const createCreditNote = async (req, res) => {
  try {
    const body = req.body;
    
    // Validation
    if (!body.invoice_id) throw new Error('invoice_id is required');
    if (!body.reason) throw new Error('reason is required');
    if (!body.items || !Array.isArray(body.items) || body.items.length === 0) {
      throw new Error('items[] is required');
    }

    // Get invoice
    const invoice = await SalesInvoice.findById(body.invoice_id);
    if (!invoice || !invoice.is_active) throw new Error('Invoice not found');
    if (invoice.status === 'Cancelled') throw new Error('Cannot create credit note against a Cancelled invoice');

    // Calculate GSTR period
    const invDate = new Date(invoice.invoice_date);
    const cnDate = new Date();
    let gstrMonth, gstrYear;

    if (cnDate.getMonth() === invDate.getMonth() && cnDate.getFullYear() === invDate.getFullYear()) {
      gstrMonth = invDate.getMonth() + 1;
      gstrYear = invDate.getFullYear();
    } else {
      gstrMonth = cnDate.getMonth() + 1;
      gstrYear = cnDate.getFullYear();
    }

    // Create credit note (without transaction)
    const creditNote = await CreditNote.create({
      invoice_id: invoice._id,
      invoice_no: invoice.invoice_no,
      invoice_date: invoice.invoice_date,
      so_id: invoice.so_id,
      customer_id: invoice.customer_id,
      customer_name: invoice.customer_name,
      customer_gstin: invoice.customer_gstin,
      reason: body.reason,
      reason_remarks: body.reason_remarks || '',
      gst_type: invoice.gst_type,
      items: body.items,
      gstr_month: gstrMonth,
      gstr_year: gstrYear,
      status: 'Draft',
      created_by: req.user._id,
    });

    // Link credit note to invoice
    await SalesInvoice.updateOne(
      { _id: invoice._id },
      { $push: { credit_note_ids: creditNote._id } }
    );

    // Post GL Entry (without transaction)
    try {
      const glLines = [
        { account_code: '1100', account_name: 'Trade Receivables', debit: 0, credit: creditNote.grand_total, narration: `Credit Note ${creditNote.cn_no} — reduce receivable` },
        { account_code: '4000', account_name: 'Sales Revenue', debit: creditNote.taxable_total, credit: 0, narration: `Revenue reversal — ${creditNote.cn_no}` },
      ];
      
      if (creditNote.gst_type === 'IGST') {
        glLines.push({ account_code: '2201', account_name: 'GST Output — IGST', debit: creditNote.igst_total, credit: 0, narration: `IGST reversal — ${creditNote.cn_no}` });
      } else {
        glLines.push(
          { account_code: '2202', account_name: 'GST Output — CGST', debit: creditNote.cgst_total, credit: 0, narration: `CGST reversal — ${creditNote.cn_no}` },
          { account_code: '2203', account_name: 'GST Output — SGST', debit: creditNote.sgst_total, credit: 0, narration: `SGST reversal — ${creditNote.cn_no}` }
        );
      }

      const glEntry = await postGLEntry({
        entry_type: 'Credit Note',
        reference_doc_type: 'CreditNote',
        reference_doc_id: creditNote._id,
        reference_doc_no: creditNote.cn_no,
        lines: glLines,
        narration: `Credit Note ${creditNote.cn_no} — ${body.reason}`,
        created_by: req.user._id,
        entry_date: cnDate,
      });

      // Update credit note with GL info
      creditNote.status = 'Issued';
      creditNote.gl_posted = true;
      creditNote.gl_posted_at = new Date();
      creditNote.gl_entry_ids = [glEntry._id];
      await creditNote.save();
      
    } catch (glError) {
      console.error('[createCreditNote] GL posting failed:', glError);
      // Don't fail credit note creation if GL fails
      creditNote.status = 'Issued';
      await creditNote.save();
    }

    // Get complete credit note with virtuals
    const result = await CreditNote.findById(creditNote._id).lean({ virtuals: true });
    
    return ok(res, { message: 'Credit note issued', data: result }, 201);
    
  } catch (e) {
    console.error('[createCreditNote] Error:', e);
    return err(res, e.message, e.message.includes('not found') ? 404 : 400);
  }
};

