// ─────────────────────────────────────────────────────────────────────────────
// GET /api/gstr1-data
// ─────────────────────────────────────────────────────────────────────────────
const getGstr1Data = async (req, res) => {
  try {
    const { month, year } = req.query;
    if (!month || !year) return err(res, 'month and year query params are required', 400);

    const m = parseInt(month);
    const y = parseInt(year);
    if (m < 1 || m > 12) return err(res, 'month must be 1–12', 400);

    const startDate = new Date(y, m - 1, 1);
    const endDate   = new Date(y, m, 0, 23, 59, 59);

    const invoices = await SalesInvoice.find({
      is_active:    true,
      status:       { $nin: ['Cancelled', 'Draft'] },
      invoice_date: { $gte: startDate, $lte: endDate },
      customer_gstin: { $ne: '' },
    }).lean({ virtuals: true });

    const creditNotes = await CreditNote.find({
      status:     'Issued',
      gstr_year:  y,
      gstr_month: m,
    }).lean();

    const b2bMap = {};
    invoices.forEach(inv => {
      const gstin = inv.customer_gstin;
      if (!b2bMap[gstin]) {
        b2bMap[gstin] = { ctin: gstin, inv: [] };
      }
      b2bMap[gstin].inv.push({
        inum:     inv.invoice_no,
        idt:      new Date(inv.invoice_date).toLocaleDateString('en-IN'),
        val:      inv.grand_total,
        pos:      String(inv.customer_state_code || '').padStart(2, '0'),
        rchrg:    'N',
        etin:     null,
        inv_typ:  'R',
        itms:     (inv.hsn_breakup || []).map((h, idx) => ({
          num:  idx + 1,
          itm_det: {
            rt:      h.gst_percentage,
            txval:   h.taxable_value,
            iamt:    h.igst_amount,
            csamt:   h.cgst_amount,
            camt:    h.cgst_amount,
            samt:    h.sgst_amount,
          },
        })),
      });
    });

    const totals = {
      total_invoices:    invoices.length,
      total_taxable_val: +invoices.reduce((s, i) => s + i.taxable_total, 0).toFixed(2),
      total_igst:        +invoices.reduce((s, i) => s + i.igst_total, 0).toFixed(2),
      total_cgst:        +invoices.reduce((s, i) => s + i.cgst_total, 0).toFixed(2),
      total_sgst:        +invoices.reduce((s, i) => s + i.sgst_total, 0).toFixed(2),
      total_grand:       +invoices.reduce((s, i) => s + i.grand_total, 0).toFixed(2),
      total_credit_notes:creditNotes.length,
      total_cn_value:    +creditNotes.reduce((s, c) => s + c.grand_total, 0).toFixed(2),
    };

    return ok(res, {
      data: {
        period: { month: m, year: y, label: `${startDate.toLocaleString('en-IN', { month: 'long' })} ${y}` },
        gstin:  (await Company.findOne({ is_active: true }))?.gstin || '',
        b2b:    Object.values(b2bMap),
        cdnr:   creditNotes.map(cn => ({
          ctin: cn.customer_gstin,
          nt: [{
            ntty: 'C',
            nt_num: cn.cn_no,
            nt_dt:  new Date(cn.createdAt).toLocaleDateString('en-IN'),
            rsn:    cn.reason,
            val:    cn.grand_total,
            itms:   [],
          }],
        })),
        totals,
      },
    });
  } catch (e) {
    console.error('[getGstr1Data] Error:', e);
    return err(res, e.message);
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/gstr3b-data
// ─────────────────────────────────────────────────────────────────────────────
const getGstr3bData = async (req, res) => {
  try {
    const { month, year } = req.query;
    if (!month || !year) return err(res, 'month and year are required', 400);

    const m = parseInt(month);
    const y = parseInt(year);
    const startDate = new Date(y, m - 1, 1);
    const endDate   = new Date(y, m, 0, 23, 59, 59);

    const invoices = await SalesInvoice.find({
      is_active:    true,
      status:       { $nin: ['Cancelled', 'Draft'] },
      invoice_date: { $gte: startDate, $lte: endDate },
    }).lean();

    const outputTax = {
      taxable_value: +invoices.reduce((s, i) => s + i.taxable_total, 0).toFixed(2),
      igst:          +invoices.reduce((s, i) => s + i.igst_total, 0).toFixed(2),
      cgst:          +invoices.reduce((s, i) => s + i.cgst_total, 0).toFixed(2),
      sgst:          +invoices.reduce((s, i) => s + i.sgst_total, 0).toFixed(2),
      total_gst:     +invoices.reduce((s, i) => s + i.gst_total, 0).toFixed(2),
    };

    let itcData = { igst: 0, cgst: 0, sgst: 0, total: 0 };
    try {
      const PurchaseInvoice = mongoose.model('PurchaseInvoice');
      const piAgg = await PurchaseInvoice.aggregate([
        { $match: { status: 'Approved', invoice_date: { $gte: startDate, $lte: endDate } } },
        { $group: { _id: null, igst: { $sum: '$igst_total' }, cgst: { $sum: '$cgst_total' }, sgst: { $sum: '$sgst_total' } } },
      ]);
      if (piAgg[0]) {
        itcData = {
          igst:  +piAgg[0].igst.toFixed(2),
          cgst:  +piAgg[0].cgst.toFixed(2),
          sgst:  +piAgg[0].sgst.toFixed(2),
          total: +(piAgg[0].igst + piAgg[0].cgst + piAgg[0].sgst).toFixed(2),
        };
      }
    } catch (_) {}

    const netTaxPayable = {
      igst: +Math.max(0, outputTax.igst - itcData.igst).toFixed(2),
      cgst: +Math.max(0, outputTax.cgst - itcData.cgst).toFixed(2),
      sgst: +Math.max(0, outputTax.sgst - itcData.sgst).toFixed(2),
    };
    netTaxPayable.total = +(netTaxPayable.igst + netTaxPayable.cgst + netTaxPayable.sgst).toFixed(2);

    return ok(res, {
      data: {
        period: { month: m, year: y },
        table_3_1: {
          description:    'Outward Taxable Supplies (other than zero rated)',
          taxable_value:  outputTax.taxable_value,
          igst:           outputTax.igst,
          cgst:           outputTax.cgst,
          sgst:           outputTax.sgst,
          invoice_count:  invoices.length,
        },
        table_4: { description: 'Eligible ITC (from Purchase Invoices)', ...itcData },
        net_tax_payable: netTaxPayable,
      },
    });
  } catch (e) {
    console.error('[getGstr3bData] Error:', e);
    return err(res, e.message);
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/ar-aging
// ─────────────────────────────────────────────────────────────────────────────
const getArAging = async (req, res) => {
  try {
    const today = new Date();

    const invoices = await SalesInvoice.find({
      is_active:      true,
      payment_status: { $nin: ['Fully Paid'] },
      status:         { $nin: ['Cancelled', 'Draft', 'Closed'] },
    })
      .select('invoice_no invoice_date due_date customer_id customer_name customer_gstin balance_due grand_total payment_status')
      .lean({ virtuals: true });

    // const customerIds = [...new Set(invoices.map(i => String(i.customer_id)))];
    // const customers = await Customer.find({ _id: { $in: customerIds } })
    //   .select('_id msme_number customer_name').lean();
    // const msmeSet = new Set(customers.filter(c => c.msme_number).map(c => String(c._id)));

    // const byCustomer = {};

    const customerIds = [...new Set(invoices.map(i => String(i.customer_id)))];
console.log('DEBUG: Customer IDs from invoices:', customerIds);

const customers = await Customer.find({ _id: { $in: customerIds } })
  .select('_id msme_number customer_name').lean();

console.log('DEBUG: Customers found in DB:', customers.map(c => ({ 
  id: c._id.toString(), 
  name: c.customer_name 
})));

// Create a map for quick customer name lookup
const customerNameMap = new Map();
customers.forEach(c => {
  customerNameMap.set(c._id.toString(), c.customer_name);
});

console.log('DEBUG: CustomerNameMap contents:', Array.from(customerNameMap.entries()));

const msmeSet = new Set(customers.filter(c => c.msme_number).map(c => c._id.toString()));
const byCustomer = {};


    invoices.forEach(inv => {
      const custKey = String(inv.customer_id);
      const dueDate = inv.due_date ? new Date(inv.due_date) : new Date(inv.invoice_date);
      const daysPast = Math.floor((today - dueDate) / 86400000);
      const isMsme = msmeSet.has(custKey);
      const msmeAlert = isMsme && daysPast > 45;

      let bucket;
      if (daysPast <= 0)         bucket = 'current';
      else if (daysPast <= 30)   bucket = '0_30';
      else if (daysPast <= 60)   bucket = '31_60';
      else if (daysPast <= 90)   bucket = '61_90';
      else if (daysPast <= 180)  bucket = '91_180';
      else                       bucket = '180_plus';

      if (!byCustomer[custKey]) {
        // byCustomer[custKey] = {
        //   customer_id:   custKey,
        //   customer_name: inv.customer_name,
        //   customer_gstin: inv.customer_gstin || '',
        byCustomer[custKey] = {
          customer_id:   custKey,
          customer_name: customerNameMap.get(custKey.toString()) || inv.customer_name || 'Unknown',
          customer_gstin: inv.customer_gstin || '',

          is_msme:       isMsme,
          current: 0, '0_30': 0, '31_60': 0, '61_90': 0, '91_180': 0, '180_plus': 0,
          total_outstanding: 0,
          msme_alert: false,
          invoices: [],
        };
      }

      byCustomer[custKey][bucket] += inv.balance_due;
      byCustomer[custKey].total_outstanding += inv.balance_due;
      if (msmeAlert) byCustomer[custKey].msme_alert = true;
      byCustomer[custKey].invoices.push({
        invoice_no:     inv.invoice_no,
        invoice_date:   inv.invoice_date,
        due_date:       dueDate,
        days_overdue:   Math.max(0, daysPast),
        balance_due:    inv.balance_due,
        payment_status: inv.payment_status,
        msme_alert:     msmeAlert,
        bucket,
      });
    });

    Object.values(byCustomer).forEach(c => {
      ['current', '0_30', '31_60', '61_90', '91_180', '180_plus'].forEach(b => {
        c[b] = +c[b].toFixed(2);
      });
      c.total_outstanding = +c.total_outstanding.toFixed(2);
    });

    const grandTotals = { current: 0, '0_30': 0, '31_60': 0, '61_90': 0, '91_180': 0, '180_plus': 0, total: 0 };
    Object.values(byCustomer).forEach(c => {
      Object.keys(grandTotals).forEach(b => {
        if (b !== 'total') grandTotals[b] += c[b] || 0;
      });
      grandTotals.total += c.total_outstanding;
    });
    Object.keys(grandTotals).forEach(k => { grandTotals[k] = +grandTotals[k].toFixed(2); });

    return ok(res, {
      data: {
        as_of:        today,
        customer_count: Object.keys(byCustomer).length,
        grand_totals: grandTotals,
        customers:    Object.values(byCustomer).sort((a, b) => b.total_outstanding - a.total_outstanding),
      },
    });
  } catch (e) {
    console.error('[getArAging] Error:', e);
    return err(res, e.message);
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/reports/monthly-revenue
// ─────────────────────────────────────────────────────────────────────────────
const getMonthlyRevenue = async (req, res) => {
  try {
    const { month, year } = req.query;
    const m = month ? parseInt(month) : new Date().getMonth() + 1;
    const y = year  ? parseInt(year)  : new Date().getFullYear();

    const startDate = new Date(y, m - 1, 1);
    const endDate   = new Date(y, m, 0, 23, 59, 59);

    const [byCustomer, byMonth, totalAgg] = await Promise.all([
      SalesInvoice.aggregate([
        { $match: { is_active: true, status: { $nin: ['Cancelled','Draft'] }, invoice_date: { $gte: startDate, $lte: endDate } } },
        { $group: { _id: '$customer_id', customer_name: { $first: '$customer_name' }, invoice_count: { $sum: 1 }, taxable_total: { $sum: '$taxable_total' }, gst_total: { $sum: '$gst_total' }, grand_total: { $sum: '$grand_total' }, outstanding: { $sum: '$balance_due' } } },
        { $sort: { grand_total: -1 } },
        { $limit: 25 },
      ]),
      SalesInvoice.aggregate([
        { $match: { is_active: true, status: { $nin: ['Cancelled','Draft'] }, invoice_date: { $gte: new Date(y - 1, m - 1, 1), $lte: endDate } } },
        { $group: { _id: { y: { $year: '$invoice_date' }, m: { $month: '$invoice_date' } }, invoice_count: { $sum: 1 }, grand_total: { $sum: '$grand_total' }, taxable_total: { $sum: '$taxable_total' } } },
        { $sort: { '_id.y': 1, '_id.m': 1 } },
      ]),
      SalesInvoice.aggregate([
        { $match: { is_active: true, status: { $nin: ['Cancelled','Draft'] }, invoice_date: { $gte: startDate, $lte: endDate } } },
        { $group: { _id: null, count: { $sum: 1 }, taxable: { $sum: '$taxable_total' }, gst: { $sum: '$gst_total' }, grand: { $sum: '$grand_total' }, outstanding: { $sum: '$balance_due' } } },
      ]),
    ]);

    return ok(res, {
      data: {
        period:      { month: m, year: y },
        summary:     totalAgg[0] || { count: 0, taxable: 0, gst: 0, grand: 0, outstanding: 0 },
        by_customer: byCustomer,
        trend_12m:   byMonth,
      },
    });
  } catch (e) {
    return err(res, e.message);
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// PUT /api/sales-orders/:id/close — Close Sales Order
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// PUT /api/sales-orders/:id/close — Close Sales Order (NO TRANSACTIONS)
// ─────────────────────────────────────────────────────────────────────────────
const closeSalesOrder = async (req, res) => {
  try {
    const so = await SalesOrder.findById(req.params.id);
    
    if (!so) throw new Error('Sales Order not found');
    if (so.status === 'Closed') throw new Error('Sales Order is already closed');
    if (so.status === 'Cancelled') throw new Error('Cannot close a Cancelled Sales Order');

    // Check all line items are delivered
    const activeLines = so.items.filter(i => !i.is_cancelled);
    const allDelivered = activeLines.every(i => i.item_status === 'Delivered');
    if (!allDelivered) {
      throw new Error('Cannot close: Not all line items are delivered');
    }

    // Check all invoices are fully paid
    const invoices = await SalesInvoice.find({
      so_id: so._id,
      is_active: true,
      status: { $nin: ['Cancelled'] },
    });

    const allPaid = invoices.every(inv => inv.payment_status === 'Fully Paid');
    if (!allPaid) {
      throw new Error('Cannot close: Not all invoices are fully paid');
    }

    // Update Sales Order
    so.status = 'Closed';
    so.closed_at = new Date();
    so.audit_log = so.audit_log || [];
    so.audit_log.push({
      changed_by: req.user._id,
      action: 'status_change',
      old_value: so.status,
      new_value: 'Closed',
      notes: 'Manually closed: all items delivered and all invoices fully paid',
    });
    await so.save();

    const result = {
      so_number: so.so_number,
      status: so.status,
      closed_at: so.closed_at,
    };

    return ok(res, { message: 'Sales Order closed successfully', data: result });
    
  } catch (e) {
    console.error('[closeSalesOrder] Error:', e);
    return err(res, e.message, e.message.includes('not found') ? 404 : 400);
  }
};

